from mk import *
from lib import fbd
STRICT["on"] = True
import math
h = 0.6 * (1 - math.cos(math.radians(12))); Ek = 5 * 10 * h; V = math.sqrt(2 * 10 * h); v0 = 5 * V / 0.015; loss = 0.5 * 0.015 * v0 ** 2 - Ek

def fig():
    g = Fig(560, 230, "מטוטלת בליסטית בשלושה שלבים: קליע m1 במהירות v0 נע לעבר גוף m2 שתלוי על חוט באורך ℓ; הקליע נעצר בגוף בנקודה A; הגוף עם הקליע עולה עד הנקודה B, שבה החוט נוטה בזווית תטא מהאנך")
    for ox, lab in ((450, "שלב ראשון"), (280, "שלב שני"), (100, "שלב שלישי")):
        g.ceiling(ox - 25, ox + 25, 40); g.heb(ox, 24, lab)
    g.line(450, 40, 450, 150, width=1.5); g.text(458, 100, "ℓ", anchor="start"); g.block(450, 164, 34, 26, "m₂"); g.circle(520, 164, 3, fill="var(--d-label)"); g.arrow(514, 156, 496, 156, "v₀", lx=520, ly=148, anchor="start"); g.text(520, 186, "m₁")
    g.line(280, 40, 280, 150, width=1.5); g.block(280, 164, 34, 26, "A"); g.text(280, 196, "m₁+m₂")
    a = math.radians(30)
    bx, by = 100 - 110 * math.sin(a), 40 + 110 * math.cos(a)
    g.line(100, 40, bx, by, width=1.5); g.block(bx, by + 10, 30, 22, "B", angle=30)
    g.line(100, 40, 100, 160, stroke="var(--d-dim)", width=1, dash="3 3"); g.angle(100, 40, 30, 240, 270, "θ", lr=44)
    return g

OPTS = ['התנע נשמר, והאנרגיה המכנית לא נשמרת', 'התנע לא נשמר, והאנרגיה המכנית נשמרת', 'שניהם נשמרים', 'שניהם לא נשמרים']
E(id="bagrut-2018-q4", year=2018, label="2018 שאלה 4", topic="momentum", sub="mom-collisions", diff=3, fig=fig,
  stem=r"עד המאה השמונה-עשרה לא ידעו למדוד מהירות של גופים מהירים, כמו קליע של רובה. בשנת $1742$ המציא המדען האנגלי בנג'מין רובינס דרך למדוד מהירות של קליעים בעזרת מטוטלת בליסטית. בשלב הראשון יורים קליע שמסתו $m_1$ אל גוף שמסתו $m_2$, שתלוי על חוט באורך $\ell$. בשלב השני הקליע פוגע בגוף בנקודה $A$ במהירות אופקית $v_0$, חודר לתוכו ונעצר בו. החדירה קצרה מאוד, ולכן הגוף כמעט לא זז בזמנה. בשלב השלישי הגוף, עם הקליע שבתוכו, עולה עד הנקודה $B$ ונעצר שם לרגע. בנקודה הזו החוט סוטה מהאנך בזווית $\theta$. מזניחים את התנגדות האוויר ואת מסת החוט. הסעיפים מתייחסים למערכת של הגוף והקליע יחד.",
  parts=[
    P("א", r"האם התנע והאנרגיה המכנית נשמרים מהרגע שהקליע פוגע בגוף ועד שהוא נעצר בתוכו? הסבירו.", choice(OPTS, 0), ["principle"], [
        S(r"התנע", r"הזמן קצר מאוד והחוט עוד אנכי, ולכן אין כוח חיצוני אופקי משמעותי. התנע נשמר", r"\Delta p_x = 0"),
        S(r"האנרגיה המכנית", r"זו התנגשות פלסטית. חלק גדול מהאנרגיה הקינטית הופך לחום ולעיוות של הגוף", r"\Delta E < 0"),
    ], r"התנע נשמר, והאנרגיה המכנית לא נשמרת"),
    P("ב", r"האם התנע והאנרגיה המכנית נשמרים מהרגע שהגוף, עם הקליע, מתחיל לזוז ועד שהוא נעצר לרגע ב-$B$? הסבירו.", choice(OPTS, 1), ["principle"], [
        S(r"התנע", r"פועלים כוח הכובד ומתיחות החוט, והכוח השקול לא אפס. לכן המהירות, וגם התנע, משתנים", r"\Sigma\vec F \ne 0"),
        S(r"האנרגיה המכנית", r"רק הכובד עושה עבודה. המתיחות ניצבת לתנועה בכל רגע, ולכן היא לא עושה עבודה", r"W_T = T\cos 90^\circ\,\Delta s = 0", eq=r"W = F\cos\theta\,\Delta s"),
    ], r"התנע לא נשמר, והאנרגיה המכנית נשמרת", key=r"תנע לא נשמר ; אנרגיה מכנית נשמרת"),
    P("ג", r"נתון: מסת הקליע $m_1 = 0.015\,\text{kg}$, מסת הגוף $m_2 = 4.985\,\text{kg}$, אורך החוט $\ell = 0.6\,\text{m}$, וזווית הסטייה המרבית $\theta = 12^\circ$. מה האנרגיה הקינטית של המערכת מיד אחרי שהגוף, עם הקליע, מתחיל לזוז מ-$A$?", num(Ek, "J"), ["principle"], [
        S(r"הגובה שהגוף עולה", r"הגובה הוא אורך החוט פחות החלק האנכי של החוט בנקודה הגבוהה", r"h = \ell - \ell\cos\theta = 0.6\,(1 - \cos 12^\circ) \approx 0.0131\,\text{m}"),
        S(r"שימור אנרגיה", r"מהסעיף הקודם האנרגיה המכנית נשמרת בעלייה. כל האנרגיה הקינטית הופכת לאנרגיית גובה. המסה הכוללת חמישה קילוגרם", r"E_k = (0.015 + 4.985) \cdot 10 \cdot 0.0131 \approx 0.656\,\text{J}", eq=r"E_k = \tfrac{1}{2}mv^2,\quad U_G = mgh"),
    ], r"$\approx 0.656\,\text{J}$", key=r"Ek=0.656 J"),
    P("ד", r"מה המהירות $v_0$ של הקליע ברגע שהוא פוגע בגוף?", num(v0, "m/s"), ["principle"], [
        S(r"מהירות הגוף אחרי ההתנגשות", r"מהאנרגיה הקינטית מהסעיף הקודם", r"\tfrac{1}{2} \cdot 5\,V^2 = 0.656 \;\Rightarrow\; V \approx 0.512\,\text{m/s}", eq=r"E_k = \tfrac{1}{2}mv^2"),
        S(r"שימור תנע בהתנגשות", r"הגוף עמד לפני הפגיעה, והקליע נשאר בתוכו", r"0.015\,v_0 + 0 = 5 \cdot 0.512 \;\Rightarrow\; v_0 \approx 170.7\,\text{m/s}", eq=r"m_A\vec v_A + m_B\vec v_B = m_A\vec u_A + m_B\vec u_B"),
    ], r"$\approx 170.7\,\text{m/s}$", key=r"v0=170.7 m/s"),
    P("ה", r"כמה אנרגיה מכנית \"אבדה\" בגלל החיכוך בזמן החדירה?", num(loss, "J"), ["principle"], [
        S(r"האנרגיה לפני ההתנגשות", r"רק לקליע יש אנרגיה קינטית", r"E_k = \tfrac{1}{2} \cdot 0.015 \cdot 170.7^2 \approx 218.5\,\text{J}", eq=r"E_k = \tfrac{1}{2}mv^2"),
        S(r"ההפרש", r"מה שאבד הוא ההפרש בין האנרגיה לפני ההתנגשות לאנרגיה שנשארה אחריה", r"218.5 - 0.656 \approx 217.9\,\text{J}"),
    ], r"$\approx 217.9\,\text{J}$", key=r"−217.88 J"),
  ],
  concepts=["מטוטלת בליסטית", "התנגשות פלסטית", "שימור תנע", "שימור אנרגיה", "אובדן אנרגיה"],
  summary=r"מטוטלת בליסטית: מזווית הסטייה מוצאים את האנרגיה, ממנה את מהירות הגוף, ומשימור תנע את מהירות הקליע. כמעט כל האנרגיה אובדת.",
  review="הנחה שלי.\nבסעיפים א ו-ב התלמיד בוחר מתוך ארבע אפשרויות.\nמה לבדוק: רק לאשר.")
